const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "<h3>Artikler</h3> <div class=\"articles-info articles-intro-info\"> <span class=\"articles-info-icon\">i</span> <div>Den tyske artikel falder ikke altid sammen med det engelske kønssystem. Derfor læres navneord bedst sammen med artiklen.</div> </div> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>•</span>Eksempler på artikler</h4> <div class=\"articles-grid\"> <div class=\"kurss-example\">Der Tisch - bord</div> <div class=\"kurss-example\">Die Tür - døren</div> <div class=\"kurss-example\">Das Messer - kniv</div> <div class=\"kurss-example\">Das Mädchen - pige</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>♂</span>Ofte DER</h4> <p class=\"artikuli-explain\">DER er ofte mandlige personer, dage, måneder, årstider og nogle ord med bestemte endelser.</p> <h5 class=\"articles-subtitle\">Vilkår</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">-er → often DER, for example: der Computer, der Lehrer <span class=\"artikuli-note\">Men ikke altid</span></div> <div class=\"kurss-example\">-ling → ofte DER, fx: der Schmetterling</div> <div class=\"kurss-example\">-ismus → ofte DER, for eksempel: der Tourismus, der Kapitalismus</div> <div class=\"kurss-example\">Mandlige personer → der Mann, der Vater</div> <div class=\"kurss-example\">Erhverv → der Lehrer, der Arzt</div> <div class=\"kurss-example\">Bilmærker → egnet til BMW, egnet til Mercedes</div> <div class=\"kurss-example\">Dage → der Montag, der Dienstag</div> <div class=\"kurss-example\">Måneder → der August, der December</div> <div class=\"kurss-example\">Årstider → der Sommer, der Winter</div> </div> <h5 class=\"articles-subtitle\">Eksempler</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">Der Mann - mand</div> <div class=\"kurss-example\">Der Vater - far</div> <div class=\"kurss-example\">Passer mandag - mandag</div> <div class=\"kurss-example\">Passer til august - august</div> <div class=\"kurss-example\">Der Sommer - sommer</div> <div class=\"kurss-example\">Der Lehrer - lærer</div> <div class=\"kurss-example\">Der Computer - computer</div> <div class=\"kurss-example\">Der Schmetterling - sommerfugl</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>♀</span>DØR ofte</h4> <p class=\"artikuli-explain\">DIE er ofte feminin person, flertal og ord, der ender på -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p> <h5 class=\"articles-subtitle\">Vilkår</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div> <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div> <div class=\"kurss-example\">-keit → die Möglichkeit</div> <div class=\"course-example\">-schaft → die Mannschaft</div> <div class=\"course-example\">-ion ​​→ die Nation</div> <div class=\"course-example\">-tät → die Universität</div> <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div> <div class=\"kurss-example\">Kvindelige personer → die Frau, die Mutter</div> <div class=\"kurss-example\">Motorcykelmærker → Harley-Davidson, Yamaha</div> <div class=\"kurss-example\">Flertal → die Autos, die Häuser</div> <div class=\"kurss-example\">Flertal næsten altid → die Autos, die Häuser, die Kinder</div> </div> <h5 class=\"articles-subtitle\">Eksempler</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">Die Frau - kvinde</div> <div class=\"kurss-example\">Die Mutter - mor</div> <div class=\"kurss-example\">Die Wohnung - lejlighed</div> <div class=\"kurss-example\">Die Rechnung - faktura</div> <div class=\"kurss-example\">Die Freiheit - frihed</div> <div class=\"kurss-example\">Die Möglichkeit - mulighed</div> <div class=\"kurss-example\">Die Mannschaft - holdet</div> <div class=\"kurss-example\">Die Nation - nation</div> <div class=\"kurss-example\">Die Universität - universitetet</div> <div class=\"kurss-example\">Die Polizei - politiet</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"articles-header\"><span>◇</span>Ofte DAS</h4> <p class=\"artikuli-explain\">DAS har ofte diminutiv med -chen / -lein, mange ord med -ment / -um og verber som navneord.</p> <h5 class=\"articles-subtitle\">Vilkår</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div> <div class=\"kurss-example\">-lein → das Fräulein</div> <div class=\"kurss-example\">-ment → das Instrument</div> <div class=\"kurss-example\">-um → das Zentrum, das Museum</div> <div class=\"kurss-example\">Metaller → das Gold, das Silber, das Eisen</div> <div class=\"kurss-example\">Kemiske grundstoffer → das Eisen, das Sauerstoff</div> <div class=\"kurss-example\">Hoteller → das Hotel</div> <div class=\"kurss-example\">Farver som navneord → das Rot, das Blau</div> <div class=\"kurss-example\">Verbum som navneord → das Essen, das Lernen</div> <div class=\"kurss-example\">Verber som navneord → das Essen, das Lernen, das Lesen</div> </div> <h5 class=\"articles-subtitle\">Eksempler</h5> <div class=\"articles-grid\"> <div class=\"kurss-example\">Das Kind - barn</div> <div class=\"kurss-example\">Das Mädchen - pige</div> <div class=\"kurss-example\">Das Häuschen - sommerhuset</div> <div class=\"kurss-example\">Das Instrument - instrument</div> <div class=\"kurss-example\">Das Zentrum - centrum</div> <div class=\"kurss-example\">Das Museum - museum</div> <div class=\"kurss-example\">Das Essen - spisning / mad</div> <div class=\"course-example\">Das Lernen - Læring</div> </div> </section> <section class=\"articles-block\"> <h4 class=\"artikuli-header\"><span>!</span>Vigtige undtagelser / skal lære med artiklen</h4> <p class=\"artikuli-explain\">For nogle ord kan artiklen ikke bestemmes pålideligt af slutningen eller den lettiske oprindelse. De studeres bedst sammen med artiklen.</p> <div class=\"articles-grid\"> <div class=\"kurss-example\">Die Tür - døren</div> <div class=\"kurss-example\">Das Messer - kniv</div> <div class=\"kurss-example\">Die Sonne - solen</div> <div class=\"kurss-example\">Der Mond - månen</div> <div class=\"kurss-example\">Das Mädchen - pige</div> <div class=\"kurss-example\">Das Auto - bil</div> <div class=\"kurss-example\">Der Käse - ost</div> <div class=\"kurss-example\">Die Gabel - gaffel</div> </div> </section> <div class=\"articles-info articles-bottom-info\"> <span class=\"articles-info-icon\">i</span> <div>Endelser og ordgrupper hjælper med at gætte artiklen, men de er ikke en 100 % sikker regel. Hvis du ikke er sikker, så lær ordet sammen med artiklen.</div> </div>",
  "kurssPronounsLesson": "\n  <h3>Pronominer</h3> <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ og Dativ - former for pronominer.</div>\n  </div> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ - hvad?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich - jeg</div><div class=\"kurss-example\">Du - dig</div><div class=\"kurss-example\">Øh - han</div><div class=\"kurss-example\">Sie - hun</div><div class=\"kurss-example\">Jeg - det</div><div class=\"kurss-example\">Wir - vi</div><div class=\"kurss-example\">Ihr - dig</div><div class=\"kurss-example\">Slips - de/hende</div><div class=\"kurss-example\">Slips - dig (høflighed)</div></div>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ - hvad?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Mich - mig</div><div class=\"kurss-example\">Dich - dig</div><div class=\"kurss-example\">Ihn - hans (v.)</div><div class=\"kurss-example\">Sie - hans (s.)</div><div class=\"kurss-example\">Mig - det</div><div class=\"kurss-example\">Han - os</div><div class=\"kurss-example\">Euch - dig</div><div class=\"kurss-example\">Sie - dem / hende</div><div class=\"kurss-example\">Sie - Dig (høflighed)</div></div>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ - til hvem?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Mir - mig</div><div class=\"kurss-example\">Dir - dig</div><div class=\"kurss-example\">Ihm - ham / det</div><div class=\"kurss-example\">Ihr - hende</div><div class=\"kurss-example\">Uns - os</div><div class=\"kurss-example\">Euch - dig</div><div class=\"kurss-example\">Ihnen - dem / for dem</div><div class=\"kurss-example\">Ihnen - til dig (høflighed)</div></div>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hvordan vælger man en formular?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> - subject of the sentence (who does?)</li><li><span class=\"case-red\">Akkusativ</span> - direct object (what?)</li><li><span class=\"case-green\">Dativ</span> - indirect object (to whom?)</li></ul>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Eksempler</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">Dich</span>. – Jeg ser dig.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">Ihn</span>. – Jeg ser ham.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">Euk</span>. – Vi kan lide dig.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">Dir</span>. – Jeg hjælper dig.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">Ihm</span> ein Buch. — I give him the book.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">Euk</span>. – Vi takker.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>The Nominative is always the subject of the sentence, while the Akkusativ and Dativ are the objects. Look at the verb and ask: <span class=\"case-red\">Hvad?</span> or <span class=\"case-green\">Wen?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "<h3>Vokaler - lange og korte</h3> <p class=\"kurss-lesson-intro\">På tysk kan vokaler være lange eller korte. Dette påvirker udtalen af ​​ordet.</p> <section class=\"course-lesson-section\"> <h4>Lang vokal</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Varm (varm) - varm</div><div class=\"kurss-example\">Tarm (få) - godt</div><div class=\"kurss-example\">Tat (tat) - arbejde / handling</div><div class=\"kurss-example\">Flur (flūr) - bande</div><div class=\"kurss-example\">Weg (vēk) - vej</div><div class=\"kurss-example\">Hytte (hūt) - hat</div><div class=\"kurss-example\">Hof (hōf) - gårdhave</div><div class=\"kurss-example\">Schlaf — sov</div></div> <p>Hvis en vokal efterfølges af én konsonant, udtales vokalen ofte lang.</p> </section> <section class=\"course-lesson-section\"> <h4>Kort vokal</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilc) - svamp</div><div class=\"kurss-example\">Wort (vort) - ord</div><div class=\"kurss-example\">Mund (munt) - mund</div><div class=\"kurss-example\">Skaldet (balt) - snart</div><div class=\"kurss-example\">Scharf (tørklæde) - ass</div><div class=\"kurss-example\">Feld (filt) - felt</div><div class=\"kurss-example\">Voll (fol) - fuld</div></div> <p>Hvis en vokal efterfølges af to eller flere konsonanter, udtales vokalen ofte kort.</p> </section> <section class=\"course-lesson-section\"> <h4>Endelser en / el / er</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Synge (zingen) - synge</div><div class=\"kurss-example\">Tragen (trāgen) - bære</div><div class=\"kurss-example\">Have (have) - have</div><div class=\"kurss-example\">Vogel (fogel) - fugl</div><div class=\"kurss-example\">Segel (zēgel) - sejl</div><div class=\"kurss-example\">Braten (brāten) - stege</div><div class=\"kurss-example\">Bogen (bōgen) - bue</div><div class=\"kurss-example\">Spiegel - spejl</div><div class=\"kurss-example\">Finger (finger) - finger</div><div class=\"kurss-example\">Grime (grime) - holder</div><div class=\"kurss-example\">Arbeiter (arbaiter) - arbejder</div><div class=\"kurss-example\">Häuser (hoizer) - hjem</div><div class=\"kurss-example\">Wieder (wieder) - igen</div><div class=\"kurss-example\">Breiter (lysere) - bredere</div></div> </section> <section class=\"course-lesson-section\"> <h4>Bogstav h som længdegrad</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rämen) - ramme</div><div class=\"kurss-example\">Ohr (ōr) - øre</div><div class=\"kurss-example\">Kohle (kōle) - kul</div><div class=\"kurss-example\">Zahl (căl) - nummer</div><div class=\"kurss-example\">Ihn (īn) - hans</div><div class=\"kurss-example\">Ihm (īm) - for skinke</div><div class=\"kurss-example\">Huhn (hūn) - kylling</div><div class=\"kurss-example\">Nahm (nām) - tog</div><div class=\"kurss-example\">Nehmen (nēmen) - at tage</div><div class=\"kurss-example\">Schuh (shuh) - sko</div></div> <p>I nogle ord forlænger h den foregående vokal. I sådanne tilfælde er h'et normalt uudtalt.</p> </section> <section class=\"course-lesson-section\"> <h4>Ender med e</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) - lampe</div><div class=\"kurss-example\">Hase (dis) - hare</div><div class=\"kurss-example\">Knabe (næb) - dreng</div><div class=\"kurss-example\">Rabe (rabe) - ravn</div></div> </section> <section class=\"course-lesson-section\"> <h4>Langt i = dvs</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Dø (dī) - artiklen \"dø\"</div><div class=\"kurss-example\">Diese (dīze) - dette / disse</div><div class=\"kurss-example\">Wieder (wieder) - igen</div><div class=\"kurss-example\">Fliege (fliege) - flyve</div><div class=\"kurss-example\">Ziege (cīge) - ged</div><div class=\"kurss-example\">Stiel (štīl) - stamme</div><div class=\"kurss-example\">Dieb (dīp) - tyv</div><div class=\"kurss-example\">Hier (hīr) - hende</div></div> <p>Langt i på tysk skrives ofte som dvs.</p> </section> <section class=\"course-lesson-section\"> <h4>Dobbelte vokaler</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (græs) - græs</div><div class=\"kurss-example\">Saat (zāt) - så</div><div class=\"kurss-example\">Staat (stat) - land</div><div class=\"kurss-example\">Beere (begravelse) - bær</div><div class=\"kurss-example\">Se (se) - sø / hav</div><div class=\"kurss-example\">Roer (bēt) - seng</div><div class=\"kurss-example\">Støvle (bōt) - båd</div><div class=\"kurss-example\">Moor (mōr) - mose</div><div class=\"kurss-example\">Moos (mōs) - mos</div></div> <p>Dobbeltvokaler udtales normalt lange.</p> </section> <section class=\"course-lesson-section\"> <h4>ä</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) - væg</div><div class=\"kurss-example\">Wände (vende) - vægge</div><div class=\"kurss-example\">Vater (fäter) - langt</div><div class=\"kurss-example\">Väter (fēter) - fædre</div><div class=\"kurss-example\">Schrank (šrank) - skab</div><div class=\"kurss-example\">Schränke (shrenke) - skabe</div><div class=\"kurss-example\">Bank (bank) - bænk / bank</div><div class=\"kurss-example\">Bänke (benke) - trin</div><div class=\"kurss-example\">Tal (fjern) - dal</div><div class=\"kurss-example\">Täler (tēler) - dale</div></div> <p>Ä er en tuning af en.</p> </section> <section class=\"course-lesson-section\"> <h4>ö</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) - rose</div><div class=\"kurss-example\">Röschen (rēschen) - roset</div><div class=\"kurss-example\">Ofen (ōfen) - ovn</div><div class=\"kurss-example\">Öfen (öfen) - ovn</div><div class=\"kurss-example\">Rock (rok) - nederdel</div><div class=\"kurss-example\">Röcke (röke) - nederdel</div></div> <p>Ö er en transponering af o.</p> </section> <section class=\"course-lesson-section\"> <h4>ü</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Kurz (kurs) - kort</div><div class=\"kurss-example\">Kürzer (kurser) - kortere</div><div class=\"kurss-example\">Kunst (kunst) - kunst</div><div class=\"kurss-example\">Künste (künste) - art</div><div class=\"kurss-example\">Mumler (muter) - mor</div><div class=\"kurss-example\">Mütter (mumler) - mødre</div></div> <p>Ü er en transponering af u.</p> </section> <section class=\"course-lesson-section\"> <h4>Dip lyde: äu</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) - træ</div><div class=\"kurss-example\">Bäume (boime) - træer</div><div class=\"kurss-example\">Haus (hus) - hus</div><div class=\"kurss-example\">Häuser (hoizer) - huse</div><div class=\"kurss-example\">Strauch (štrauh) - busk</div><div class=\"kurss-example\">Sträucher (štroiher) - buske</div><div class=\"kurss-example\">Maus (maus) - mus</div><div class=\"kurss-example\">Mäuse (moise) - mus</div></div> </section> <section class=\"course-lesson-section\"> <h4>Dip: eu</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Heute (hoite) - i dag</div><div class=\"kurss-example\">Leute (loite) - mennesker</div><div class=\"kurss-example\">Neu (noi) - ny</div><div class=\"kurss-example\">Neun (noin) - ni</div></div> </section> <section class=\"course-lesson-section\"> <h4>Diplomatik: ei</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Mein (main) - mine</div><div class=\"kurss-example\">Dein (dain) - din</div><div class=\"kurss-example\">Sein (zain) - hun / hende / være</div><div class=\"kurss-example\">Frei (frai) - gratis</div><div class=\"kurss-example\">Arbeiten (arbaiten) - at arbejde</div></div> </section> <section class=\"course-lesson-section\"> <h4>2. forelæsningsudtalenoter</h4> <ul class=\"kurss-summary-list\"><li>I ordene ich, nicht, rechnen, zeichnen udtales \"ch\" blød</li><li>I ordene arbeiten og zeichnen udtales \"ei\" som \"ai\"</li><li>\"sp\" i begyndelsen af ​​ordet udtales som \"šp\"</li><li>I verbet tun udtales bogstavet \"u\" langt</li></ul> </section> <section class=\"course-lesson-section\"> <h4>Oversigt</h4> <ul class=\"kurss-summary-list\"><li>Én konsonant efter en vokal → ofte en lang vokal</li><li>To eller flere konsonanter → ofte en kort vokal</li><li>H kan forlænge en vokal</li><li>Dvs ofte betyder lang i</li><li>Dobbeltvokaler er normalt lange</li></ul> </section>",
  "kurssConsonantsLesson": "<h3>Konsonanter og bogstavkombinationer</h3> <p class=\"kurss-lesson-intro\">På tysk udtales nogle konsonanter og bogstavkombinationer anderledes, end de er skrevet. Dette foredrag indeholder de vigtigste eksempler for begynderen.</p> <section class=\"course-lesson-section\"> <h4>Konsonanter</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Das Rad (rāt) - hjul</div><div class=\"kurss-example\">Die Räder (rēder) - hjul</div><div class=\"kurss-example\">Dårlig (bāt) - dårlig</div><div class=\"kurss-example\">Bäder (bäder) - bade</div></div> <p>Konsonanter i slutningen af ​​et ord udtales ofte ikke, som de er skrevet.</p> </section> <section class=\"course-lesson-section\"> <h4>ch</h4> <p>\"ch\" kan udtales blød eller hård. I nogle ord lyder det som \"h\", i andre nærmere \"k\".</p> <div class=\"course-examples\"><div class=\"course-example\">Rechnen (rehnen) - beregne</div><div class=\"course-example\">Zeichnen (caihnen) - uafgjort</div><div class=\"course-example\">Nicht (niht) - ikke</div><div class=\"course-example\">Schlecht (šleht) - dårlig</div><div class=\"course-example\">Mich (mih) - mig</div><div class=\"course-example\">Dich (dih) - dig</div><div class=\"kurss-example\">Strauch (štrauh) - busk</div><div class=\"kurss-example\">Noch (nej) - stadig</div><div class=\"kurss-example\">Nacht (naht) - nat</div></div> </section> <section class=\"course-lesson-section\"> <h4>Sch</h4> <p>\"sch\" på tysk udtales som letisk \"š\".</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule - skole</div><div class=\"kurss-example\">Schüler - elev</div><div class=\"kurss-example\">Schiff - skib</div><div class=\"kurss-example\">Schraube - skrue</div></div> </section> <section class=\"course-lesson-section\"> <h4>Sp og st i begyndelsen af ​​ordet</h4> <p>I begyndelsen af ​​et ord eller en stavelse udtales \"sp\" ofte som \"šp\" og \"st\" som \"št\".</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielen (špīlen) - at spille</div><div class=\"kurss-example\">Sprung (šprung) - hop</div><div class=\"kurss-example\">Stehen (štēen) - at stå</div><div class=\"kurss-example\">Stald (štal) - stald</div><div class=\"kurss-example\">Stå (štant) - stilling / sted</div></div> </section> <section class=\"course-lesson-section\"> <h4>qu</h4> <p>\"qu\" udtales normalt som \"kv\" på tysk.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) - tortur</div><div class=\"kurss-example\">Quartier (kvartīr) - kvarter / indkvartering</div><div class=\"kurss-example\">Quer (kvær) - på tværs</div></div> </section> <section class=\"course-lesson-section\"> <h4>S og z</h4> <p>''et' i begyndelsen af ​​et ord lyder ofte som et 'z'. Bogstavet \"z\" på tysk lyder som lettisk \"c\".</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Sagen (zāgen) - at sige</div><div class=\"kurss-example\">Synge (zingen) - at synge</div><div class=\"kurss-example\">Rose (rōze) - rose</div><div class=\"kurss-example\">Zahl (kylling) - nummer</div><div class=\"kurss-example\">Zeit (cait) - tid</div><div class=\"kurss-example\">Zink (zink) - zink</div></div> </section> <section class=\"course-lesson-section\"> <h4>v</h4> <p>På tysk udtales 'v' ofte som 'f'. Med fremmede ord lyder det ofte som det lettiske \"v\".</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fäter) - langt</div><div class=\"kurss-example\">Von (fon) - no</div><div class=\"kurss-example\">Viel (fīl) - mange</div><div class=\"kurss-example\">Vier (fīr) - ild</div><div class=\"kurss-example\">Villa (villa) - villa</div><div class=\"kurss-example\">Klavier (klaver) - klaver</div></div> </section> <section class=\"course-lesson-section\"> <h4>X og y</h4> <p>'x' udtales som 'ks'. \"y\" udtales som \"ü\" i nogle ord.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (feliks) - Felix</div><div class=\"kurss-example\">Axt (akst) - økse</div><div class=\"kurss-example\">Mystik (mustik) - mystik</div><div class=\"kurss-example\">Nyx (nūks) - Nikse</div><div class=\"kurss-example\">Mythe (mund) - myte</div></div> </section> <section class=\"course-lesson-section\"> <h4>ß</h4> <p>\"ß\" udtales som \"s\" på tysk.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (füs) - fod</div><div class=\"kurss-example\">Füße (füse) - fødder</div><div class=\"kurss-example\">Grüße (grüße) - hilsner</div></div> </section> <section class=\"course-lesson-section\"> <h4>Oversigt</h4> <ul class=\"kurss-summary-list\"><li>Sch → š</li><li>Sp / st i begyndelsen → šp / št</li><li>Qu → kv</li><li>Z → c</li><li>V ofte → f</li><li>X → ks</li><li>SS → s</li></ul> </section>",
  "kurssVerbBasicsLesson": "<h3>Grundlæggende om verber</h3> <p class=\"kurss-lesson-intro\">1. verber og bøjninger af forelæsningen.</p> <section class=\"course-lesson-section\"> <h4>Verber</h4> <div class=\"course-examples\"><div class=\"course-example\">Kommen - at komme</div><div class=\"course-example\">Gehen - at gå</div><div class=\"course-example\">Stehen - at stå</div><div class=\"course-example\">Synge - at synge</div></div> </section> <section class=\"course-lesson-section\"> <h4>Kommen</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich komme - jeg kommer</div><div class=\"course-example\">Du kommst - du kommer</div><div class=\"course-example\">Er kommt - han kommer</div><div class=\"course-example\">Sie kommt - hun kommer</div><div class=\"course-example\">Wir kommen - vi kommer</div><div class=\"course-example\">Ihr kommt - du kommer</div><div class=\"kurss-example\">kommen — de / de kommer</div></div> </section> <section class=\"course-lesson-section\"> <h4>Gehen</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich gehe - jeg går</div><div class=\"course-example\">Du gehst - du går</div><div class=\"course-example\">Er geht - han går</div><div class=\"course-example\">Sie geht - hun går</div><div class=\"course-example\">Wir gehen - vi går</div><div class=\"course-example\">Ihr geht - du går</div><div class=\"kurss-example\">gehen — de/hun går</div></div> </section> <section class=\"course-lesson-section\"> <h4>Stehen</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich stehe - jeg står</div><div class=\"course-example\">Du stehst - du står</div><div class=\"course-example\">Er steht - han står</div><div class=\"course-example\">Sie steht - hun står</div><div class=\"course-example\">Wir stehen - vi står</div><div class=\"course-example\">Ihr steht - du står</div><div class=\"kurss-example\">stehen — de/hun står</div></div> </section> <section class=\"course-lesson-section\"> <h4>Synge</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">singen — jeg synger</div><div class=\"kurss-example\">ich komme — du synger</div><div class=\"kurss-example\">du kommst — han synger</div><div class=\"kurss-example\">er kommt — hun synger</div><div class=\"kurss-example\">sie kommt — vi synger</div><div class=\"kurss-example\">wir kommen — du synger</div><div class=\"kurss-example\">ihr kommt — de / de synger</div></div> </section> <section class=\"course-lesson-section\"> <h4>2. forelæsningsverber</h4> <div class=\"course-examples\"><div class=\"course-example\">Spielen - at spille</div><div class=\"course-example\">Arbeiten - at arbejde</div><div class=\"course-example\">Fragen - at spørge</div><div class=\"course-example\">Antworten - at svare</div><div class=\"course-example\">Rechnen - at beregne</div><div class=\"course-example\">Zeichnen - at tegne</div><div class=\"course-example\">Tun - at gøre</div></div> </section> <section class=\"course-lesson-section\"> <h4>Spil</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich spielt - jeg spiller</div><div class=\"course-example\">Du spielst - du spiller</div><div class=\"course-example\">Er spielt - han spiller</div><div class=\"course-example\">Sie spielt - hun spiller</div><div class=\"course-example\">Wir spielen - vi spiller</div><div class=\"course-example\">Ihr spielt - du spiller</div><div class=\"kurss-example\">sie kommen — de/hende i spillet</div></div> </section> <section class=\"course-lesson-section\"> <h4>Arbeiten</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — jeg arbejder</div><div class=\"kurss-example\">du gehst — du arbejder</div><div class=\"kurss-example\">er geht — han arbejder</div><div class=\"kurss-example\">sie geht — hun arbejder</div><div class=\"kurss-example\">wir gehen — vi arbejder</div><div class=\"kurss-example\">ihr geht — du arbejder</div><div class=\"kurss-example\">sie gehen — de/hendes arbejde</div></div> </section> <section class=\"course-lesson-section\"> <h4>Fragen</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich frage - spørger jeg</div><div class=\"course-example\">Du fragst - du spørger</div><div class=\"course-example\">Er fragt - spørger han</div><div class=\"course-example\">Sie fragt - spørger hun</div><div class=\"course-example\">Wir fragen - vi spørger</div><div class=\"course-example\">Ihr fragt - du spørger du</div><div class=\"kurss-example\">ich stehe — de/de spørger</div></div> </section> <section class=\"course-lesson-section\"> <h4>Svar</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">du stehst — jeg svarer</div><div class=\"kurss-example\">er steht — du svarer</div><div class=\"kurss-example\">sie steht — svarer han</div><div class=\"kurss-example\">wir stehen — svarer hun</div><div class=\"kurss-example\">ihr steht — vi svarer</div><div class=\"kurss-example\">sie stehen — du svarer</div><div class=\"kurss-example\">ich singe — de / de svarer</div></div> </section> <section class=\"course-lesson-section\"> <h4>Rechnen</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich rechne - jeg beregner</div><div class=\"course-example\">Du rechnest - du beregner</div><div class=\"course-example\">Er rechnet - beregner han</div><div class=\"course-example\">Sie rechnet - hans udregning</div><div class=\"course-example\">Wir rechnen - vi vi beregner</div><div class=\"kurss-example\">du singst — du regner</div><div class=\"kurss-example\">er singt — de / hendes faktura</div></div> </section> <section class=\"course-lesson-section\"> <h4>Zeichnen</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich zeichne - jeg tegner</div><div class=\"course-example\">Du zeichnest - du tegner</div><div class=\"course-example\">Er zeichnet - han tegner</div><div class=\"course-example\">Sie zeichnet - hun tegner</div><div class=\"course-example\">Wir zeichnen - vi tegner</div><div class=\"course-example\">Ihr zeichnet - dig du tegner</div><div class=\"kurss-example\">sie singt — de/hendes tegner</div></div> </section> <section class=\"course-lesson-section\"> <h4>Der</h4> <div class=\"course-examples\"><div class=\"course-example\">Ich tue - det gør jeg</div><div class=\"course-example\">Du tus - det gør du</div><div class=\"course-example\">Eh - det gør han</div><div class=\"course-example\">Sie tut - det gør hun</div><div class=\"course-example\">Wir tun - det gør vi</div><div class=\"course-example\">Ihr tut - det gør du</div><div class=\"kurss-example\">wir singen — de/de gør det</div></div> </section>",
  "kurssSentenceStructureLesson": "<h3>Sætningsstruktur</h3> <p class=\"kurss-lesson-intro\">I en spørgsmålssætning kommer verbet normalt først på tysk.</p> <section class=\"course-lesson-section\"> <h4>Eksempler</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Du kommer.</div><div class=\"kurss-example\">Kommst du? — Kommer du?</div><div class=\"kurss-example\">Er singt. — Han synger.</div><div class=\"kurss-example\">Singt er? — Synger han?</div><div class=\"kurss-example\">Stehst du? — Står du?</div><div class=\"kurss-example\">Ja, ich stehe. — Ja, jeg står.</div><div class=\"kurss-example\">Geht ihr? — Går I?</div><div class=\"kurss-example\">Ja, wir gehen. — Ja, vi går.</div></div> </section> <section class=\"course-lesson-section\"> <h4>Spørgsmål med \"var\"</h4> <p>Hvis et spørgsmål starter med et spørgsmålsord, kommer verbet på tysk som regel umiddelbart efter spørgsmålsordet.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Was machst du?</div><div class=\"kurss-example\">Was tut er? — Hvad laver han?</div><div class=\"kurss-example\">Was tut sie? — Hvad laver hun?</div><div class=\"kurss-example\">Was tun sie? — Hvad laver de?</div></div> </section> <section class=\"course-lesson-section\"> <h4>Negation med \"nicht\"</h4> <p>Når negationen \"nicht\" refererer til et verbum, kommer det normalt efter verbet på tysk.</p> <div class=\"course-examples\"><div class=\"course-example\">Ich spiele nicht. – Jeg spiller ikke.</div><div class=\"kurss-example\">Ich spiele nicht. — Paul spørger ikke.</div><div class=\"kurss-example\">Paul fragt nicht. — Han kommer ikke.</div><div class=\"kurss-example\">Er kommt nicht. — De/de synger ikke.</div></div> </section> <section class=\"course-lesson-section\"> <h4>Sætninger fra foredrag 2</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Sie singen nicht. — Spiller du?</div><div class=\"kurss-example\">Spielst du? — Nein, jeg spiller ikke, jeg arbejder.</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Paul spørger ikke, han arbejder.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Arbejder du?</div><div class=\"kurss-example\">Arbeitest du? — Nein, jeg arbejder ikke, jeg synger.</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Hvad laver Paul?</div><div class=\"kurss-example\">Was tut Paul? — Han spiller.</div><div class=\"kurss-example\">Er spielt. — Hvad laver Maria?</div><div class=\"kurss-example\">Was tut Marie? — Hun synger.</div><div class=\"kurss-example\">Sie singt. — Paul spiller, men Maria synger.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Synger du?</div><div class=\"kurss-example\">Singt ihr? — Nein, vi synger ikke, vi arbejder.</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Hvad laver Paul og Maria?</div><div class=\"kurss-example\">Was tun Paul und Marie? — De spørger.</div><div class=\"kurss-example\">Sie fragen. — De svarer ikke.</div><div class=\"kurss-example\">Sie antworten nicht. — Wen arbejder?</div><div class=\"kurss-example\">Wer arbeitet? — Vi arbejder.</div><div class=\"kurss-example\">Wir arbeiten. — Vi zählt og tegner.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — De kommer, spørger, svarer, arbejder, leger, synger og går.</div></div> </section>",
  "kurssLesson2": "<h3>Foredrag 2</h3> <p class=\"kurss-lesson-intro\">Anden forelæsning: dialoger, ord, udtale, grammatik og oversættelse.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div> <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div> <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div> <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div> <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div> <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div> <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div> <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div> <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div> <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div> </div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">spielen — at spille • Spil</div> <div class=\"course-example\">Nein - nej</div> <div class=\"course-example\">Ikke - nej</div> <div class=\"kurss-example\">nein — at arbejde</div> <div class=\"kurss-example\">nicht — at spørge</div> <div class=\"kurss-example\">arbeiten — hvad laver han?</div> <div class=\"kurss-example\">fragen — hvad gør de/de?</div> <div class=\"course-example\">Aber - men</div> <div class=\"kurss-example\">was tut er? — svar</div> <div class=\"kurss-example\">was tun sie? — beregne</div> <div class=\"kurss-example\">aber — uafgjort</div> <div class=\"kurss-example\">antworten — Marie</div> </div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">rechnen — I ordene ich, nicht, rechnen, zeichnen udtales lyden ch sagte, omtrent som i de lettiske ord: technika, Frīdrihs.</div><div class=\"kurss-example\">zeichnen — lyd efterfulgt af i.</div><div class=\"kurss-example\">Marie — Konsonantklyngen sp udtales som šp: spielen (špīlen).</div><div class=\"kurss-example\">Vārdos ich, nicht, rechnen, zeichnen skaņu ch izrunā mīksti, apmēram tā, kā latviski vārdos: technika, Frīdrihs.</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>1</span>Afslutning med e</h4> <div class=\"lesson1-grammar-note\">Hvis verbets stamme ender på t, d, chn, så er endelserne -st og -t foran e.</div> <h5 class=\"lesson2-subtitle\">arbeiten</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">Jeg arbejder</div><div class=\"course-example\">Du arbeite</div><div class=\"course-example\">Er arbeit</div><div class=\"course-example\">Sie arbeit</div><div class=\"course-example\">Wir arbeiten</div><div class=\"course-example\">Ihr arbeit</div><div class=\"course-example\">Sie arbeiten</div></div> <h5 class=\"lesson2-subtitle\">rechnen</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">Ich recchne</div><div class=\"course-example\">Du rechnest</div><div class=\"course-example\">Er rechnet</div><div class=\"course-example\">Sie rechnet</div><div class=\"course-example\">Wir rechnen</div><div class=\"course-example\">Ihr rechnet</div><div class=\"course-example\">Sie rechnen</div></div> <h5 class=\"lesson2-subtitle\">tun</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">Jeg tirsdag</div><div class=\"course-example\">Du tust</div><div class=\"course-example\">Eh tut</div><div class=\"course-example\">Sie tut</div><div class=\"course-example\">Wir tun</div><div class=\"course-example\">Ihr tut</div><div class=\"course-example\">Sie tun</div></div> </section> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>2</span>Det pågældende ord</h4> <div class=\"lesson1-grammar-note\">I spørgende sætninger, der begynder med spørgsmålsordet, for eksempel: wer? was? wie? warum? osv., udsagnsordet står umiddelbart efter spørgsmålsordet.</div> <div class=\"lesson1-card-grid\"><div class=\"course-example\">Var tust du? - Was machst du?</div><div class=\"kurss-example\">Vārdos arbeiten, zeichnen divskani ei izrunā apmēram kā latviešu plato e skaņu, kam seko i.</div><div class=\"kurss-example\">Līdzskaņu kopojumu sp izrunā kā šp: spielen (špīlen).</div><div class=\"kurss-example\">Darbības vārdā tun u izrunājams gari visās personās.</div></div> </section> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>3</span>Negation med nicht</h4> <div class=\"lesson1-grammar-note\">Hvis negationen nicht refererer til et verbum, så kommer det negerede ord efter verbet.</div> <div class=\"lesson1-card-grid\"><div class=\"course-example\">Er kommt nicht. – Han kommer ikke.</div><div class=\"kurss-example\">ich arbeite</div></div> </section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversætte</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-training-wrap\"> <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 2 translation card\"> <span class=\"lesson1-training-progress\">Foredrag 2 · Oversat: 1 / 15</span> <span class=\"lesson1-training-text\">Wen spørger?</span> </button> <p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser det næste klik det næste kort.</p> </div> </div> </details>",
  "kurssLesson6": "<h3>Foredrag 6</h3> <p class=\"kurss-lesson-intro\">Tal, flertal, omlyd og flertalsformer af substantiver.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — er, er, ligger</div><div class=\"kurss-example\">der Bleistift (bleištift) — blyant</div><div class=\"kurss-example\">einige (einige) — nogle</div><div class=\"kurss-example\">hinlegen — lægge ned</div><div class=\"kurss-example\">legt hin — læg ned</div><div class=\"kurss-example\">wieder (vīder) — igen</div><div class=\"kurss-example\">aufmachen — løsne</div><div class=\"kurss-example\">er macht auf — han løsner</div><div class=\"kurss-example\">anspitzen (anšpicen) — at spytte</div><div class=\"kurss-example\">er spitzt an — han spytter</div><div class=\"kurss-example\">sich setzen — at sætte sig ned</div><div class=\"kurss-example\">setzt sich — sætter sig</div><div class=\"kurss-example\">der Schlüssel (šlūsel) — nøgle</div><div class=\"kurss-example\">das Fenster (fenster) — vindue</div><div class=\"kurss-example\">die Tafel (dī tāfel) — tavle</div><div class=\"kurss-example\">der Garten — have</div><div class=\"kurss-example\">der Löffel — ske</div><div class=\"kurss-example\">zählen (cēlen) — tælle</div><div class=\"kurss-example\">die Nadel — nål</div><div class=\"kurss-example\">was ist das — hvad er det?</div><div class=\"kurss-example\">der Hammer — forhammer</div><div class=\"kurss-example\">die Hämmer — forhammer</div><div class=\"kurss-example\">der Deckel (dēr dekel) — låg</div><div class=\"kurss-example\">der Teller — tallerken</div><div class=\"kurss-example\">der Wagen — vogn</div><div class=\"kurss-example\">der Schlitten — slæde, slæde</div><div class=\"kurss-example\">das Ding — ting</div><div class=\"kurss-example\">die Dinge — ting</div><div class=\"kurss-example\">wie sind die Dinge? — hvad er tingene?</div><div class=\"kurss-example\">voll (fōl) — fuld</div><div class=\"kurss-example\">leer (lēr) — tom</div><div class=\"kurss-example\">schwer (švēr) — tung, svær</div><div class=\"kurss-example\">leicht — lys</div><div class=\"kurss-example\">der Eimer — spand</div><div class=\"kurss-example\">wieviel (vīfīl) — hvor mange</div><div class=\"kurss-example\">wieviel Nadeln — hvor mange nåle</div><div class=\"kurss-example\">hier (hīr) — hende</div><div class=\"kurss-example\">dort — der</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä ir patskaņa a pārskanojums, un to izrunā kā īso vai garo šauro e.</div><div class=\"kurss-example\">Piemēri: das Mädchen (mētchen), die Bänke (dī benke), der Vater (dēr fāter), die Väter (dī fēter).</div><div class=\"kurss-example\">ü ir patskaņa u pārskanojums. To izrunājot, lūpas ļoti jāapaļo un jāmēģina ar apaļi veidotām lūpām izrunāt i.</div><div class=\"course-example\">Eksempler: fünf, der Schlüssel (schlüsel).</div><div class=\"course-example\">Udtale ö med afrundede læber, forsøge at udtale e: der Löffel.</div><div class=\"course-example\">En fordoblet vokal repræsenterer en lang vokal: leer.</div><div class=\"course-example\">En fordoblet eu udtales som oi: neun (noin).</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatik og forklaringer</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Piemēri: fünf, der Schlüssel (šlūsel).</div><div class=\"kurss-example\">ö izrunā ar apaļi veidotām lūpām, mēģinot izrunāt e: der Löffel.</div><div class=\"kurss-example\">Divkāršots patskanis apzīmē garu patskani: leer (lēr).</div><div class=\"kurss-example\">Divskani eu izrunā kā oi: neun (noin).</div><div class=\"kurss-example\">Salikta darbības vārda uzsvērtais priedēklis tagadnē atdalās no darbības vārda un stāv teikuma beigās.</div><div class=\"kurss-example\">Piemēri: hinlegen — og flertalsform: der Schüler ist klein • Die Schüler synd klein.</div><div class=\"kurss-example\">Skaitļa vārds viens ir visās trīs kārtās, ja to lieto ar lietvārdu: vīriešu kārtā ein, sieviešu kārtā eine, vidējā kārtā ein.</div><div class=\"kurss-example\">Piemēri: ein Schüler — das ist ein Hammer • Det er en nål — das ist eine Nadel • De er hamre — das sind Hämmer • De er nåle - das sind Nadeln.</div><div class=\"kurss-example\">Skaitļi: eins, zwei, drei, vier (fīr), fünf, sechs (zeks), sieben (zīben), acht, neun (noin), zehn (cēn).</div><div class=\"kurss-example\">Saitaiņa vācu valodā ir vienskaitļa un daudzskaitļa forma: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Norādāmais vietniekvārds tas latviešu valodā mainās skaitlī un kārtā, bet vācu valodā lieto vienu formu: das.</div><div class=\"kurss-example\">Piemēri: tas ir veseris — el, -er flertal tager -n.</div><div class=\"kurss-example\">Der Wagen — die Nadeln • Die Feder — die Federn.</div><div class=\"kurss-example\">Vīriešu un vidējās kārtas lietvārdi ar galotni -die Mütter (mødre) • Die Tochter (datter) — die Töchter (døtre).</div><div class=\"kurss-example\">Piemēri: der Hammer — das sind Wagen • Das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Sieviešu kārtas lietvārdi ar galotni -I en fortællende sætning står prædikatverbet på andenpladsen: er legt den Schlüssel hin • Dann legt er den Schlüssel hin.</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversætte</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 6 translation card\"><span class=\"lesson1-training-progress\">Lektion 6 · Oversæt: 1 / 21</span><span class=\"lesson1-training-text\">Paul tager en blyant og tegner.</span></button><p class=\"lesson1-training-hint\">Klik på kort for at se den tyske oversættelse. Efter svaret viser det næste klik det næste kort.</p></div></div> </details>",
  "kurssLesson5": "<h3>Foredrag 5</h3> <p class=\"kurss-lesson-intro\">Wen?, akkusativ, sitzen, fragen og -in endelse.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div> <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div> <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div> <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div> <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div> <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div> <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div> <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div> <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div> <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div> <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div> <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">sitzen (zicen) — at sidde</div> <div class=\"kurss-example\">fragen (frāgen) — at spørge</div> <div class=\"kurss-example\">der Lehrer (dēr lērer) — lærer</div> <div class=\"kurss-example\">gut (gūt) — godt</div> <div class=\"kurss-example\">wen (vēn) — hvad</div> <div class=\"kurss-example\">loben — ros</div> <div class=\"kurss-example\">der Schüler (šūler) — elev</div> <div class=\"kurss-example\">klein — lille</div> <div class=\"kurss-example\">groß (grōs) — stor</div> <div class=\"kurss-example\">die Lehrerin — lærer</div> <div class=\"kurss-example\">die Schülerin — skolepige</div> <div class=\"kurss-example\">schlecht (šleht) — dårlig</div> <div class=\"kurss-example\">tadeln — pelt</div> <div class=\"kurss-example\">oder (ōder) — eller</div> <div class=\"kurss-example\">das Kind (kint) — barn</div> <div class=\"kurss-example\">artig (ārtich) — høflig</div> <div class=\"kurss-example\">die Mutter — mor</div> <div class=\"kurss-example\">lieben (līben) — at elske</div> <div class=\"kurss-example\">der Vater (fāter) — langt</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">tz ir dubultots z skanis un izrunājams kā z: sitzen (zicen).</div> <div class=\"kurss-example\">v vācu vārdos izrunā kā f: der Vater (fāter).</div> <div class=\"kurss-example\">ß sauc par escet un izrunā kā latviešu s: groß (grōs), weiß (veis).</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativ og akkusativ</h4><div class=\"lesson1-grammar-note\">på dansk svarer nominativ på spørgsmålet hvem?, og akkusativ på spørgsmålet hvad?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vācu valodā nominatīvā jautājums ir wer? personām un was? priekšmetiem.</div><div class=\"kurss-example\">Akuzatīvā jautājums ir wen? personām un was? priekšmetiem.</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Ændring af artikler til akkusativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Sidden</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"course-example\">Sie sitzen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Fragen + akkusativ</h4><div class=\"lesson1-grammar-note\">Verbet fragen på tysk kræver en akkusativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sie sitzen</div><div class=\"kurss-example\">Wen fragt der Lehrer?</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">- i slutningen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div><div class=\"kurss-example\">Daudz sieviešu kārtas vārdu atvasina ar galotni -Dø Lehrerin</div><div class=\"kurss-example\">die Lehrerin</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Stedet for verbet</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">die Schülerin</div><div class=\"kurss-example\">Stāstāmā teikumā darbības vārds stāv otrā vietā.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversætte</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 5 translation card\"><span class=\"lesson1-training-progress\">Lektion 5 · Oversæt: 1/16</span><span class=\"lesson1-training-text\">Hvad elsker far?</span></button><p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser det næste klik det næste kort.</p></div></div> </details>",
  "kurssLesson4": "<h3>Foredrag 4</h3> <p class=\"kurss-lesson-intro\">Akkusativ, nehmen, hinlegen, hinausgehen og adjektiver.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">Nehmen (nēmen) - at tage</div><div class=\"course-example\">Er nimmt (nimt) — han tager</div><div class=\"kurss-example\">nehmen (nēmen) — fjerklædt</div><div class=\"kurss-example\">er nimmt (nimt) — fjerklædt</div><div class=\"kurss-example\">der Federhalter (dēr fēderhalter) — show</div><div class=\"kurss-example\">einen Federhalter — sort</div><div class=\"kurss-example\">zeigen — hvid</div><div class=\"kurss-example\">schwarz (švarc) — fjer</div><div class=\"kurss-example\">weiß (veis) — fjer</div><div class=\"kurss-example\">die Feder (dī fēder) — spids</div><div class=\"kurss-example\">eine Feder — lægge ned</div><div class=\"kurss-example\">spitz (špic) — læg ned</div><div class=\"kurss-example\">hinlegen — pige</div><div class=\"kurss-example\">legt hin — kniv</div><div class=\"kurss-example\">das Mädchen (mētchen) — kniv</div><div class=\"kurss-example\">das Messer — skarp</div><div class=\"kurss-example\">ein Messer — stub</div><div class=\"kurss-example\">scharf — så</div><div class=\"kurss-example\">stumpf (štumpf) — ud</div><div class=\"kurss-example\">dann — gå ud, gå ud</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinaus — en, -er, -el er ubetonede, så e i disse i enderne er svagt hørbare: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">hinausgehen — H på tysk kan både være en lyd og en længdemarkør for den foregående vokal.</div><div class=\"kurss-example\">Galotnes -Hvis h er en længdemarkør, udtales den ikke som en lyd: nehmen (nēmen).</div><div class=\"kurss-example\">h vācu valodā var būt gan skaņa, gan garumzīme iepriekšējam patskanim.</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akkusativ</h4><div class=\"lesson1-grammar-note\">I femininum og intetkøn er akkusativ lig med nominativ. Kun mænds skifter runde.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ja h ir garumzīme, to neizrunā kā skaņu: nehmen (nēmen).</div><div class=\"kurss-example\">Ja patskanim seko tikai viens līdzskanis, patskani izrunā gari: die (dī) Feder (fēder), den (dēn).</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"course-example\">Ich nehme</div><div class=\"course-example\">Du nimmst</div><div class=\"course-example\">Er/sie nimmt</div><div class=\"course-example\">Wir nehmen</div><div class=\"course-example\">Ihr nehmt</div><div class=\"course-example\">Sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronominer</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Adskillelige verber</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjektiver</h4><div class=\"lesson1-grammar-note\">Hvis et adjektiv er et adjektiv i en sætning, ændres det ikke i rækkefølge eller antal.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div><div class=\"kurss-example\">er — Das Messer ist klein</div><div class=\"kurss-example\">sie — Die Messer synd klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negation med nicht</h4><div class=\"lesson1-grammar-note\">Hvis nicht negerer et adjektiv, står det foran det negative ord.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">es — Der Federhalter ist nicht weiß</div><div class=\"kurss-example\">daudzskaitlī — Das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversætte</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecture 4 translation card\"><span class=\"lesson1-training-progress\">Lektion 4 · Oversæt: 1/16</span><span class=\"lesson1-training-text\">Pigen tager et fjerskaft.</span></button><p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser det næste klik det næste kort.</p></div></div></details>",
  "kurssLesson3": "<h3>Foredrag 3</h3> <p class=\"kurss-lesson-intro\">Tredje forelæsning: dialoger, ord, udtale, grammatik og oversættelse.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">Wer - hvad</div><div class=\"course-example\">Var - hvad</div><div class=\"kurss-example\">wer — her</div><div class=\"kurss-example\">was — der</div><div class=\"kurss-example\">hier — Der Tisch bord</div><div class=\"kurss-example\">dort — bord</div><div class=\"kurss-example\">der Tisch — bænk</div><div class=\"kurss-example\">ein Tisch — bænk</div><div class=\"kurss-example\">die Bank — ligge ned</div><div class=\"kurss-example\">eine Bank — er der/er en bog her?</div><div class=\"kurss-example\">liegen — en bog</div><div class=\"kurss-example\">liegt hier ein Buch? — en bog</div><div class=\"kurss-example\">das Buch — hænge</div><div class=\"kurss-example\">ein Buch — billede</div><div class=\"kurss-example\">hängen — billede</div><div class=\"kurss-example\">das Bild — tavle</div><div class=\"kurss-example\">ein Bild — tavle</div><div class=\"kurss-example\">die Tafel — nogen, hvad</div><div class=\"kurss-example\">eine Tafel — er</div><div class=\"kurss-example\">wie — tyk, fed</div><div class=\"kurss-example\">ist — notesbog</div><div class=\"kurss-example\">dick — notesbog</div><div class=\"kurss-example\">das Heft — tynd, tynd</div><div class=\"kurss-example\">ein Heft — lav</div><div class=\"kurss-example\">dünn — høj</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">niedrig — lyd på tysk repræsenteres af f.eks.: ligge (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">hoch — Ck er dobbelt k: pik (dikk).</div><div class=\"kurss-example\">Garo ī skaņu vācu valodā apzīmē ar ie: liegen (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">ck ir divkāršs k: dick (dikk).</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Sætningsemne</h4><div class=\"lesson1-grammar-note\">Emnet for en sætning på tysk besvarer spørgsmålet wer? / hvad? og står nominativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Īpašības un apstākļu vārdos galotne -Med wer? spørger efter personer.</div><div class=\"kurss-example\">Ja galotne -Er hvad? spørger om emner.</div><div class=\"kurss-example\">Ar wer? jautā pēc personām.</div><div class=\"kurss-example\">Ar was? jautā pēc priekšmetiem.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artikler</h4><div class=\"lesson1-grammar-note\">Tysk i sproget har substantivet 3 kasus: hankøn, hunkøn og intetkøn. Navneord indledes normalt af et ord kaldet en artikel. Dette ord er ikke oversat.</div><h5 class=\"lesson2-subtitle\">Noteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer singt? — der</div><div class=\"kurss-example\">Was liegt hier? — dø</div><div class=\"kurss-example\">vīriešu kārta — das</div><div class=\"kurss-example\">sieviešu kārta — Flertalsbestemt artiklen for alle tre runder er terning.</div><div class=\"kurss-example\">vidējā kārta — die Tische</div><div class=\"kurss-example\">Daudzskaitlī noteiktais artikuls visām trim kārtām ir die.</div><div class=\"kurss-example\">der Tisch — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nenoteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">die Bank — ein</div><div class=\"kurss-example\">das Heft — eine</div><div class=\"kurss-example\">vīriešu kārta — ein</div><div class=\"kurss-example\">sieviešu kārta — Den ubestemte artikel har ingen flertal.</div><div class=\"kurss-example\">vidējā kārta — Tische</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Egennavne</h4><div class=\"lesson1-grammar-note\">Ingen artikler før egennavne.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ein Tisch — Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Stedet for verbet</h4><div class=\"lesson1-grammar-note\">I en fortællende sætning kommer verbet på andenpladsen.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ein Heft — Hier hängt en karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Stehen / liegen / hængen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.<br><br></div><div class=\"kurss-example\">Hier hängt eine Karte.<br><br></div><div class=\"kurss-example\">Vāciski par priekšmetiem, kas stāv vertikāli, saka, ka priekšmets stāv:<br>der Tisch steht<br>die Bank steht</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversætte</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecture 3 translation card\"><span class=\"lesson1-training-progress\">Lektion 3 · Oversæt: 1 / 22</span><span class=\"lesson1-training-text\">Tæller du?</span></button><p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser det næste klik det næste kort.</p></div></div></details>",
  "kurssLesson7": "<h3>Foredrag 7</h3> <p class=\"kurss-lesson-intro\">Syvende lektion: kommandoudtryk, tiltaleform og flertal.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">Hans, singe ein Lied! Was machst du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">Synge — at synge</div><div class=\"course-example\">Synge — synge</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div><div class=\"kurss-example\">singen — synge</div><div class=\"kurss-example\">singe — song</div><div class=\"kurss-example\">singt — You</div><div class=\"kurss-example\">singen Sie — tælle</div><div class=\"kurss-example\">das Lied (das līt) — ung dame</div><div class=\"kurss-example\">Sie — møller</div><div class=\"kurss-example\">zählen — åben</div><div class=\"kurss-example\">das Fräulein (froilein) — vindue</div><div class=\"kurss-example\">der Müller — all</div><div class=\"kurss-example\">öffnen — mirror</div><div class=\"kurss-example\">das Fenster (fenster) — klud, moppe</div><div class=\"kurss-example\">alle — skovl</div><div class=\"kurss-example\">der Spiegel (špīgel) — kost</div><div class=\"kurss-example\">der Lappen — skovl</div><div class=\"kurss-example\">der Spaten — skål</div><div class=\"kurss-example\">der Besen — værelse</div><div class=\"kurss-example\">die Schaufel — kyst</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">die Schüssel — Sp i begyndelsen af ​​et ord eller en stavelse udtales som šp: der Spiegel (for špīgel).</div><div class=\"kurss-example\">das Zimmer — Sch udtales som letisk š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">das Ufer (ūfer) — Diftongen äu udtales som letisk oi: das Fräulein (das froilein).</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Kommandoer udtryk</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp vārda vai zilbes sākumā izrunā kā šp: der Spiegel (dēr špīgel).</div><div class=\"kurss-example\">sch izrunā kā latviešu š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">Divskani äu izrunā kā latviešu oi: das Fräulein (das froilein).</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Flertal kommando</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pavēles izteiksme vienskaitļa 2. personā atbilst darbības vārda 2. personai vienskaitlī bez personu galotnes -Kommandoformen i 2. person flertal ligner 2. person nuværende flertal, men bruges uden pronomen.</div><div class=\"kurss-example\">Piemēri: antworte!, arbeite!, öffne!, zeichne!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Adresseform med Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ļoti bieži galotne -Adresseformen med \"Du\" ligner 3. person flertal. Pronomenet Sie skrives med stort bogstav og står efter verbet.</div><div class=\"kurss-example\">Pavēles forma 2. personā daudzskaitlī līdzinās tagadnes daudzskaitļa 2. personai, bet tiek lietota bez vietniekvārda.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Piemēri: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Øvelse</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecture 7 exercise card\"><span class=\"lesson1-training-progress\">Lektion 7 · Übung: 1/16</span><span class=\"lesson1-training-text\">Fragen - at spørge</span></button><p class=\"lesson1-training-hint\">Tryk på kortet for at se kommandoformularer.</p></div></div></details>",
  "kurssLesson1": "<h3>Foredrag 1</h3> <p class=\"kurss-lesson-intro\">Første forelæsning: nutid verber, navneord, udtale, grammatik og oversæt.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Nutid verber</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-info\">Verber og deres konjugationer i nutid.</div> <div class=\"lesson1-verb-cards\"> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — at komme</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>Jeg kommer</span><span>du</span><strong>kommst</strong><span>Du kommer</span><span>er / sie</span><strong>kommt</strong><span>Han/hun kommer</span><span>wir</span><strong>kommen</strong><span>Vi kommer</span><span>ihr</span><strong>kommt</strong><span>I kommer</span><span>sie / Sie</span><strong>kommen</strong><span>De / Du kommer</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — gå</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>Jeg går</span><span>du</span><strong>gehst</strong><span>Du går</span><span>er / sie</span><strong>geht</strong><span>Han/hun går</span><span>wir</span><strong>gehen</strong><span>Vi går</span><span>ihr</span><strong>geht</strong><span>Du udstøder</span><span>sie / Sie</span><strong>gehen</strong><span>De / du går</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — at stå</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>Jeg står</span><span>du</span><strong>stehst</strong><span>Du står</span><span>er / sie</span><strong>steht</strong><span>Han/hun står</span><span>wir</span><strong>stehen</strong><span>Vi står</span><span>ihr</span><strong>steht</strong><span>Du står</span><span>sie / Sie</span><strong>stehen</strong><span>De/Du står</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>singen — at synge</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>Jeg synger</span><span>du</span><strong>singst</strong><span>Du synger</span><span>er / sie</span><strong>singt</strong><span>Han/hun synger</span><span>wir</span><strong>singen</strong><span>Vi synger</span><span>ihr</span><strong>singt</strong><span>Du synger</span><span>sie / Sie</span><strong>singen</strong><span>De / du synger</span></div> </article> </div> <section class=\"lesson1-block\"> <h4>Eksempler</h4> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div> </section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Den omtrentlige udtale af ord er angivet i parentes med lettiske bogstaver.<br>Dette bør også følges i fremtidige forelæsninger.</span></div> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vīr) — vi</div><div class=\"kurss-example\">Vārdā “wir” burts i tiek izrunāts gari.</div><div class=\"kurss-example\">kommen (komen) — at komme</div><div class=\"kurss-example\">gehen (gē-en) - at gå</div><div class=\"kurss-example\">stehen (štē-en) - stå</div><div class=\"kurss-example\">singen (zingen) — synge</div><div class=\"kurss-example\">du (dū) kommst — du kommer</div><div class=\"kurss-example\">er (ēr) kommt — han kommer</div><div class=\"kurss-example\">sie (zī) kommt — hun kommer</div><div class=\"kurss-example\">wer (vēr) — hvad?</div><div class=\"kurss-example\">ja (jā) — ja</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vārdu pareiza izruna, apzīmēta latviešu burtiem, ir dota lekcijās.</div><div class=\"kurss-example\">Wir (vīr) — vi. Ordet wir udtales altid langt.</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiv</h4><div class=\"lesson1-grammar-note\">Grundformen af ​​et verbum. Normalt ender infinitiv på -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Nuværende afslutninger</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Remove <span class=\"lesson1-ending-accent\">-da</span> from base forms of the verb and add the ending.</strong></p><p>Eksempel: kommen → komm + slutning</p><div class=\"lesson1-ending-process\" aria-label=\"The process of forming the present ending\"><div class=\"lesson1-ending-step\"><strong>Kommen</strong><span>Grundform</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>remove <span class=\"lesson1-ending-accent\">-da</span></strong><span>Roden bliver tilbage</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>Komm</strong><span>Rod</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>Ende</strong><span>E/st/t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>Komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>Kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>Kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"course-example\">Ich → -e</div><div class=\"course-example\">Du → -st</div><div class=\"course-example\">Er / sie → -t</div><div class=\"course-example\">Wir → -en</div><div class=\"course-example\">Ihr → -t</div><div class=\"course-example\">Sie → -en</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Eksempler</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -Ich komme</div><div class=\"kurss-example\">du → -Du kommst</div><div class=\"kurss-example\">er / sie → -Er kommet</div><div class=\"kurss-example\">wir → -Wir kommen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Spørgsmålssætninger</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>I en tysk spørgsmålssætning flytter verbet normalt til den første position.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ihr → -på dansk:<br><br></div><div class=\"kurss-example\">sie → -Tysk på:<br><br></div><div class=\"kurss-example\">ich komme<br></div><div class=\"kurss-example\">du kommst<br></div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Personforskel</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div><div class=\"kurss-example\">Latviešu valodā:<br>Tu nāc.<br>Vai tu nāc?</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversætte</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-training-wrap\"> <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 1 training card\"> <span class=\"lesson1-training-progress\">Lektion 1 · Oversat: 1/11</span> <span class=\"lesson1-training-text\">Kommer du?</span> </button> <p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser det næste klik det næste kort.</p> </div> </div> </details>"
};

